alter table ai_guard_budget add column enabled boolean default true,add column cap_microusd bigint default 2000000,add column spent_microusd bigint default 0,add column reserved_microusd bigint default 0,add column envelope_microusd bigint default 56000,add column max_calls int default 1,add column per_call_ceiling_microusd bigint default 56000,add column max_parallel int default 1,add column max_actor_parallel int default 1,add column cooldown_seconds int default 0,add column hourly_limit int default 17,add column daily_limit int default 35,add column model text default 'gpt-6.1-terra',add column pricing_revision text default 'test-pricing',add column verified_credit_expires_at timestamptz;
alter table ai_guard_requests add column envelope_microusd bigint,add column pricing_revision text,add column reviewed_generation bigint,add column created_at timestamptz default clock_timestamp();
alter table explanation_replacement_versions add column actor_id uuid,add column question_id text,add column base_version text,add column before_snapshot jsonb,add column after_snapshot jsonb,add column committed_at timestamptz,add column write_transaction bigint;
alter table question_explanation_overrides add column replacement_revision uuid,add column figure_status text;
create table ai_guard_reviewed_state(id boolean primary key,generation bigint,manifest_sha256 text,source_commit text);
insert into ai_guard_reviewed_state values(true,1,'manifest','source');
create table ai_guard_reviewed_questions(question_id text,generation bigint);
create table figure_image_limits(id boolean primary key,enabled boolean,capture boolean,captured int,max_new int);
insert into figure_image_limits values(true,true,true,0,50);
create table figure_queue_config(id boolean primary key,enabled boolean,capture_new boolean,max_rows int);
insert into figure_queue_config values(true,true,true,1000);
create table figure_queue_jobs(request_id uuid primary key,question_id text,explanation_sha256 text,state text,figure_needs jsonb,needs_state text,image_status text,attempts int default 0,created_at timestamptz default clock_timestamp(),lease_until timestamptz);
create table explanation_figure_candidates(id uuid primary key,question_id text,status text,explanation_sha256 text,section_sha256 text,image_sha256 text,section_heading text,section_title text,section_anchor text,source_url text,license_url text,license text,image_mime text,image_bytes bytea,attribution text);
create schema figure_model_private;
create table figure_model_private.batch(id boolean primary key,enabled boolean,model_enabled boolean,funding_mode text,cash_authorized boolean,funding_evidence_sha text,no_cash boolean,credit_until timestamptz,model text,pricing_revision text,reserve_cost bigint,model_calls int,max_model_calls int,charged bigint,cap bigint,targets text[],max_output_tokens int);
create table figure_model_private.operations(operation_id uuid primary key,candidate_id uuid,key text,binding jsonb,state text,model text,pricing_revision text,reserved_cost bigint,max_output_tokens int,send_token uuid,image_bytes bytea,source_evidence jsonb);
create table figure_model_private.events(operation_id uuid,event text);
create table figure_model_private.text_plans(request_id uuid,actor_id uuid,question_id text,base_version text);
create table figure_model_private.text_reservations(request_id uuid);
create function figure_text_cash_allowed(uuid,uuid,text,text) returns boolean language sql as $$ select false $$;
create function explanation_replacement_base(p_question text) returns jsonb language sql as $$ select jsonb_build_object('version',encode(sha256(convert_to(jsonb_build_object('shared',(select to_jsonb(e) from question_explanation_overrides e where e.question_id=p_question),'reviewed_static_ref',null)::text,'UTF8')),'hex')) $$;
create function explanation_replacement_status(p_actor uuid,p_question text,p_id uuid) returns jsonb language plpgsql as $$ declare r ai_guard_requests%rowtype;begin select * into r from ai_guard_requests where id=p_id;if not found then return jsonb_build_object('status','not_found');end if;if r.actor_id<>p_actor or r.question_id<>p_question then return jsonb_build_object('status','denied');end if;return jsonb_build_object('status',case when r.result_committed then 'completed' when r.state='closed' then 'not_written' else 'pending' end,'value',(select to_jsonb(e) from question_explanation_overrides e where e.question_id=p_question));end $$;
create function figure_model_locked_text(p_question text,p_sha text) returns text language sql as $$ select explanation from question_explanation_overrides where question_id=p_question and encode(sha256(convert_to(explanation,'UTF8')),'hex')=p_sha $$;
create function figure_continuation_bound(jsonb,uuid) returns boolean language sql as $$ select false $$;
create function ai_guard_image_eligible(text,text) returns boolean language sql as $$ select true $$;
